/*
 * Unit tests for key-number-scaled volume envelopes (SF2 generators
 * keyNumToVolEnvHold / keyNumToVolEnvDecay) in TinySoundFont.
 *
 * The tests render the single-preset font keyvolenv.sf2 (generated by
 * gen_keyvolenv_sf2.py) and measure the *audible* envelope of the
 * rendered waveform, judging each envelope segment with SF2 semantics:
 *
 *   - SF2 time unit: envelope times are declared in timecents
 *     (1200 * log2(seconds)); the expected musical time in seconds is
 *     2^(timecents/1200) after applying the key-number scaling
 *     hold(K)  = 2^((-2400 + 100*(60-K))/1200) s
 *     decay(K) = 2^((-1200 +  50*(60-K))/1200) s
 *
 *   - SF2 volume semantics: the amp envelope holds at full level, then
 *     decays exponentially (tsf.h uses a -9.226 neper slope so that
 *     "decay" is the time to fall to ~-80 dB) until the sustain level
 *     is reached; sustainVolEnv = 400 centibels = 40 dB attenuation,
 *     i.e. a sustain gain of exactly 0.01.
 *
 * Test 1 (key scaling): the same instrument played at keys 48/60/72 must
 *   show hold durations and decay contours that follow the declared key
 *   scaling, in seconds.
 *
 * Test 2 (output sample rate): at output rates 22050/44100/48000 Hz the
 *   voice envelope must express the same musical time (seconds), not the
 *   same sample count.  Pitch (zero-crossing frequency of the 441 Hz
 *   carrier) and volume (windowed peak amplitude) are measured through
 *   independent channels so the criteria can tell a pitch change apart
 *   from a volume change: across keys the pitch changes by 2^((K-60)/12)
 *   while the envelope times follow key scaling; across sample rates
 *   both pitch (Hz) and envelope times (s) stay constant.
 *
 * Build & run (from the repository root):
 *   cc -O2 -o tests/test_keyvolenv tests/test_keyvolenv.c -lm
 *   ./tests/test_keyvolenv tests/keyvolenv.sf2
 */

#include <math.h>
#include <stdio.h>
#include <stdlib.h>

#define TSF_IMPLEMENTATION
#include "../tsf.h"

/* Soundfont definition (must match gen_keyvolenv_sf2.py). */
#define HOLD_TIMECENTS   (-2400.0)  /* holdVolEnv */
#define DECAY_TIMECENTS  (-1200.0)  /* decayVolEnv */
#define KEYNUM_TO_HOLD     (100.0)  /* keyNumToVolEnvHold, tc/key */
#define KEYNUM_TO_DECAY     (50.0)  /* keyNumToVolEnvDecay, tc/key */
#define SUSTAIN_GAIN        (0.01)  /* sustainVolEnv 400 cb = 40 dB */
#define BASE_KEY              60    /* key scaling reference key */
#define SINE_HZ            (441.0)  /* sample frequency at root key */

/* tsf.h renders the amp envelope with this exponential slope constant
 * (level(t) = exp(-9.226 * t / decay), i.e. decay = time to ~-80 dB). */
#define DECAY_NEPERS 9.226

/* Analysis window.  The envelope is updated per 64-sample block
 * (TSF_RENDER_EFFECTSAMPLEBLOCK), so use a window of two blocks. */
#define WINDOW 128

static int g_failures = 0;
static int g_checks = 0;

static void check(int ok, const char *what, double got, double want, double tol)
{
	g_checks++;
	if (ok) {
		printf("ok   %-58s got %.6g want %.6g (+/-%.6g)\n",
		       what, got, want, tol);
	} else {
		printf("FAIL %-58s got %.6g want %.6g (+/-%.6g)\n",
		       what, got, want, tol);
		g_failures++;
	}
}

/* SF2 time semantics: timecents -> seconds. */
static double timecents_to_sec(double tc) { return pow(2.0, tc / 1200.0); }

/* Expected segment times after key-number scaling (SF2 2.01, 8.1.2). */
static double expected_hold_sec(int key)
{
	return timecents_to_sec(HOLD_TIMECENTS + KEYNUM_TO_HOLD * (BASE_KEY - key));
}
static double expected_decay_sec(int key)
{
	return timecents_to_sec(DECAY_TIMECENTS + KEYNUM_TO_DECAY * (BASE_KEY - key));
}
/* Expected carrier frequency: pitch follows the key, not the envelope. */
static double expected_freq_hz(int key)
{
	return SINE_HZ * pow(2.0, (key - BASE_KEY) / 12.0);
}

/* Render one note monophonically and return the float buffer. */
static float *render_note(tsf *font, int sample_rate, int key,
                          double seconds, int *out_frames)
{
	tsf *copy = tsf_copy(font);
	int frames;
	float *buf;
	if (!copy) { fprintf(stderr, "tsf_copy failed\n"); exit(2); }
	tsf_set_output(copy, TSF_MONO, sample_rate, 0.0f);
	if (!tsf_note_on(copy, 0, key, 1.0f)) {
		fprintf(stderr, "tsf_note_on failed for key %d\n", key);
		exit(2);
	}
	frames = (int)(seconds * sample_rate);
	buf = (float *)malloc((size_t)frames * sizeof(float));
	if (!buf) { fprintf(stderr, "out of memory\n"); exit(2); }
	tsf_render_float(copy, buf, frames, 0);
	tsf_close(copy);
	*out_frames = frames;
	return buf;
}

/* Measured envelope of one rendered note, in seconds and relative gain. */
struct envelope_meas {
	double a0;            /* peak amplitude during hold (absolute)   */
	double hold_end;      /* time [s] where the level leaves ~full   */
	double decay_sec;     /* exponential decay time constant [s]     */
	int decay_valid;      /* 0 if no decay contour could be measured */
	double sustain_rel;   /* sustained level relative to a0          */
	double sustain_ripple;/* max deviation of sustained level, rel.  */
};

/*
 * Extract the volume envelope from the waveform with a windowed peak
 * detector.  This measures only the amplitude contour; the 441 Hz
 * carrier (pitch) is invisible to it except as the signal being scaled.
 */
static struct envelope_meas measure_envelope(const float *buf, int frames,
                                             int sample_rate)
{
	struct envelope_meas m;
	int nw = frames / WINDOW, i, j;
	double *amp = (double *)malloc((size_t)nw * sizeof(double));
	if (!amp) { fprintf(stderr, "out of memory\n"); exit(2); }

	for (i = 0; i < nw; i++) {
		double peak = 0.0;
		for (j = 0; j < WINDOW; j++) {
			double v = fabs(buf[i * WINDOW + j]);
			if (v > peak) peak = v;
		}
		amp[i] = peak;
	}

	m.a0 = 0.0;
	for (i = 0; i < nw; i++)
		if (amp[i] > m.a0) m.a0 = amp[i];

	/* Hold segment: level stays at full amplitude; the hold ends at the
	 * first window whose peak falls below 98% of the full level. */
	m.hold_end = (double)frames / sample_rate;
	for (i = 0; i < nw; i++) {
		if (amp[i] < 0.98 * m.a0) {
			m.hold_end = (double)(i * WINDOW) / sample_rate;
			break;
		}
	}

	/* Decay segment: exponential contour.  Fit a line to ln(amp) over
	 * the windows between 90% of full level and 3x the sustain level;
	 * the SF2 volume semantics say level(t) = exp(-9.226 t / decay). */
	{
		double lo = 3.0 * SUSTAIN_GAIN * m.a0, hi = 0.90 * m.a0;
		double sx = 0, sy = 0, sxx = 0, sxy = 0, n = 0;
		for (i = 0; i < nw; i++) {
			double t, y;
			if (amp[i] < lo || amp[i] > hi) continue;
			t = (i + 0.5) * WINDOW / sample_rate;
			y = log(amp[i]);
			sx += t; sy += y; sxx += t * t; sxy += t * y; n += 1;
		}
		if (n < 4) {
			/* No measurable decay contour (e.g. the segment was
			 * skipped): report as invalid so the checks fail. */
			m.decay_sec = 0.0;
			m.decay_valid = 0;
		} else {
			m.decay_sec = -DECAY_NEPERS * (sxx - sx * sx / n)
			                     / (sxy - sx * sy / n);
			m.decay_valid = 1;
		}
	}

	/* Sustain segment: constant level at the sustain gain.  Average the
	 * peak over the last 0.2 s and track the worst deviation to prove
	 * the level is flat (a level, not a slope). */
	{
		int tail = (int)(0.2 * sample_rate / WINDOW);
		int start = nw - tail;
		double sum = 0, dev = 0, mean;
		if (start < 0) start = 0;
		for (i = start; i < nw; i++) sum += amp[i];
		mean = sum / (nw - start);
		for (i = start; i < nw; i++) {
			double d = fabs(amp[i] - mean);
			if (d > dev) dev = d;
		}
		m.sustain_rel = mean / m.a0;
		m.sustain_ripple = dev / mean;
	}

	free(amp);
	return m;
}

/*
 * Measure the carrier frequency through positive-going zero crossings
 * with linear interpolation.  This channel is sensitive to pitch and
 * insensitive to the (slow) volume envelope.
 */
static double measure_freq(const float *buf, int frames, int sample_rate,
                           double t_from, double t_to)
{
	int i = (int)(t_from * sample_rate), end = (int)(t_to * sample_rate);
	int crossings = 0;
	double first_t = 0, last_t = 0;
	if (end > frames) end = frames;
	for (; i + 1 < end; i++) {
		if (buf[i] <= 0.0f && buf[i + 1] > 0.0f) {
			double frac = (double)buf[i] / (buf[i] - buf[i + 1]);
			double t = (i + frac) / sample_rate;
			if (crossings == 0) first_t = t;
			last_t = t;
			crossings++;
		}
	}
	if (crossings < 2) return 0.0;
	return (crossings - 1) / (last_t - first_t);
}

/* Tolerance for hold-end times: envelope granularity is one 64-sample
 * block and the detector window is two blocks, plus a 2% margin. */
static double hold_tol(int sample_rate, double expected)
{
	return (WINDOW + 64.0) / sample_rate + 0.02 * expected;
}

static void test_key_scaling(tsf *font)
{
	static const int keys[] = { 48, 60, 72 };
	const int rate = 44100;
	double hold[3], decay[3];
	int k;

	printf("# test 1: key-number-scaled hold and decay at %d Hz\n", rate);
	for (k = 0; k < 3; k++) {
		int frames;
		float *buf = render_note(font, rate, keys[k], 1.5, &frames);
		struct envelope_meas m = measure_envelope(buf, frames, rate);
		char what[128];

		snprintf(what, sizeof(what), "key %d hold duration [s]", keys[k]);
		check(fabs(m.hold_end - expected_hold_sec(keys[k]))
		      <= hold_tol(rate, expected_hold_sec(keys[k])),
		      what, m.hold_end, expected_hold_sec(keys[k]),
		      hold_tol(rate, expected_hold_sec(keys[k])));

		snprintf(what, sizeof(what), "key %d decay time constant [s]", keys[k]);
		check(m.decay_valid &&
		      fabs(m.decay_sec - expected_decay_sec(keys[k]))
		      <= 0.08 * expected_decay_sec(keys[k]),
		      what, m.decay_sec, expected_decay_sec(keys[k]),
		      0.08 * expected_decay_sec(keys[k]));

		snprintf(what, sizeof(what), "key %d sustain level (rel. full)", keys[k]);
		check(fabs(m.sustain_rel - SUSTAIN_GAIN) <= 0.3 * SUSTAIN_GAIN,
		      what, m.sustain_rel, SUSTAIN_GAIN, 0.3 * SUSTAIN_GAIN);

		snprintf(what, sizeof(what), "key %d sustain is flat (ripple)", keys[k]);
		check(m.sustain_ripple <= 0.15, what, m.sustain_ripple, 0.0, 0.15);

		hold[k] = m.hold_end;
		decay[k] = m.decay_sec;
		free(buf);
	}

	/* The declared scaling is 100 tc/key for hold (x2 per octave) and
	 * 50 tc/key for decay (x2 per two octaves): the measured contour
	 * ratios between keys must match those musical ratios. */
	check(fabs(hold[0] / hold[1] - 2.0) <= 0.2,
	      "hold(48)/hold(60) ratio", hold[0] / hold[1], 2.0, 0.2);
	check(fabs(hold[1] / hold[2] - 2.0) <= 0.2,
	      "hold(60)/hold(72) ratio", hold[1] / hold[2], 2.0, 0.2);
	check(fabs(decay[0] / decay[1] - sqrt(2.0)) <= 0.15,
	      "decay(48)/decay(60) ratio", decay[0] / decay[1], sqrt(2.0), 0.15);
	check(fabs(decay[1] / decay[2] - sqrt(2.0)) <= 0.15,
	      "decay(60)/decay(72) ratio", decay[1] / decay[2], sqrt(2.0), 0.15);
}

static void test_sample_rate_independence(tsf *font)
{
	static const int rates[] = { 22050, 44100, 48000 };
	int r, k;

	printf("# test 2: same musical time at different output sample rates\n");
	for (r = 0; r < 3; r++) {
		int frames;
		float *buf = render_note(font, rates[r], BASE_KEY, 1.5, &frames);
		struct envelope_meas m = measure_envelope(buf, frames, rates[r]);
		double freq = measure_freq(buf, frames, rates[r], 0.02, 0.20);
		char what[128];

		snprintf(what, sizeof(what), "rate %d hold duration [s]", rates[r]);
		check(fabs(m.hold_end - expected_hold_sec(BASE_KEY))
		      <= hold_tol(rates[r], expected_hold_sec(BASE_KEY)),
		      what, m.hold_end, expected_hold_sec(BASE_KEY),
		      hold_tol(rates[r], expected_hold_sec(BASE_KEY)));

		snprintf(what, sizeof(what), "rate %d decay time constant [s]", rates[r]);
		check(m.decay_valid &&
		      fabs(m.decay_sec - expected_decay_sec(BASE_KEY))
		      <= 0.08 * expected_decay_sec(BASE_KEY),
		      what, m.decay_sec, expected_decay_sec(BASE_KEY),
		      0.08 * expected_decay_sec(BASE_KEY));

		snprintf(what, sizeof(what), "rate %d sustain level (rel. full)", rates[r]);
		check(fabs(m.sustain_rel - SUSTAIN_GAIN) <= 0.3 * SUSTAIN_GAIN,
		      what, m.sustain_rel, SUSTAIN_GAIN, 0.3 * SUSTAIN_GAIN);

		/* Pitch channel: the carrier must stay at 441 Hz regardless of
		 * the output rate - only the envelope time base is resampled. */
		snprintf(what, sizeof(what), "rate %d carrier frequency [Hz]", rates[r]);
		check(fabs(freq - expected_freq_hz(BASE_KEY))
		      <= 0.015 * expected_freq_hz(BASE_KEY),
		      what, freq, expected_freq_hz(BASE_KEY),
		      0.015 * expected_freq_hz(BASE_KEY));

		free(buf);
	}

	/* Pitch-vs-volume discrimination: across keys the zero-crossing
	 * channel must track 2^((K-60)/12) while the envelope channel
	 * (checked in test 1) tracks the key-scaled times.  A defect that
	 * turns key scaling into a pitch shift (or vice versa) fails here. */
	printf("# test 2b: pitch follows the key, independently of the envelope\n");
	for (k = 0; k < 3; k++) {
		static const int keys[] = { 48, 60, 72 };
		const int rate = 44100;
		int frames;
		float *buf = render_note(font, rate, keys[k], 0.3, &frames);
		double freq = measure_freq(buf, frames, rate, 0.02, 0.10);
		char what[128];
		snprintf(what, sizeof(what), "key %d carrier frequency [Hz]", keys[k]);
		check(fabs(freq - expected_freq_hz(keys[k]))
		      <= 0.015 * expected_freq_hz(keys[k]),
		      what, freq, expected_freq_hz(keys[k]),
		      0.015 * expected_freq_hz(keys[k]));
		free(buf);
	}
}

int main(int argc, char **argv)
{
	const char *sf2_path = (argc > 1 ? argv[1] : "keyvolenv.sf2");
	tsf *font = tsf_load_filename(sf2_path);
	if (!font) {
		fprintf(stderr, "could not load %s\n", sf2_path);
		return 2;
	}
	if (tsf_get_presetcount(font) != 1) {
		fprintf(stderr, "expected exactly 1 preset in %s\n", sf2_path);
		return 2;
	}

	test_key_scaling(font);
	test_sample_rate_independence(font);

	tsf_close(font);
	printf("# %d/%d checks passed\n", g_checks - g_failures, g_checks);
	if (g_failures) {
		printf("RESULT: FAIL (%d failures)\n", g_failures);
		return 1;
	}
	printf("RESULT: PASS\n");
	return 0;
}
